(()=>{var l=document.querySelector(".demo-list");if(l){let o=document.getElementById("demo-filter"),c=document.getElementById("demo-count");o&&(o.hidden=!1,o.addEventListener("click",d=>{let n=d.target.closest("[data-filter]");if(!n)return;let i=n.dataset.filter;o.querySelectorAll("[data-filter]").forEach(t=>{let e=t===n;t.classList.toggle("is-active",e),t.setAttribute("aria-pressed",String(e))});let s=0;for(let t of l.children){let e=i==="all"||t.dataset.category===i;t.hidden=!e,e&&s++}c.textContent=`Showing ${s} demo${s===1?"":"s"}`}))}})();
